 static void Check(bool v,string n){if(!v)throw new Exception(n);count++;Console.WriteLine("PASS "+n);}static void Pump(){var frame=new DispatcherFrame();Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.ApplicationIdle,new Action(()=>frame.Continue=false));Dispatcher.PushFrame(frame);}static void Wait(Func<bool> done){var end=DateTime.UtcNow.AddSeconds(25);while(!done()&&DateTime.UtcNow<end){Pump();Thread.Sleep(5);}if(!done())throw new Exception("Timeout");}static void Finish(Task t){Wait(()=>t.IsCompleted);t.GetAwaiter().GetResult();}
 static IEnumerable<T> All<T>(DependencyObject r)where T:DependencyObject{for(int i=0;i<VisualTreeHelper.GetChildrenCount(r);i++){var c=VisualTreeHelper.GetChild(r,i);if(c is T)yield return (T)c;foreach(var x in All<T>(c))yield return x;}}
 static string[] Nav(){return ((StackPanel)Get("navigation")).Children.OfType<Button>().Select(b=>Convert.ToString(b.Content)).ToArray();}static void Mode(int n){Finish((Task)Call("ChangeInterfaceMode",n));main.UpdateLayout();}static void Page(string n){Call("Page",n);Pump();main.UpdateLayout();}static int Port(){var listener=new System.Net.Sockets.TcpListener(System.Net.IPAddress.Loopback,0);listener.Start();int p=((System.Net.IPEndPoint)listener.LocalEndpoint).Port;listener.Stop();return p;}
 static void Save(string name){main.UpdateLayout();var bmp=new RenderTargetBitmap((int)main.ActualWidth,(int)main.ActualHeight,96,96,PixelFormats.Pbgra32);bmp.Render(main);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bmp));using(var file=File.Create(Path.Combine(output,name+".png")))encoder.Save(file);}
