  bool hostsSeen=false;var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(20)};timer.Tick+=(s,e)=>{var w=app.Windows.Cast<Window>().FirstOrDefault(v=>v!=main&&v.Title=="Кастомный WARP · hosts");if(w==null)return;timer.Stop();w.Left=-10000;w.Top=-10000;hostsSeen=All<Button>(w).Any(b=>b.Name=="routingHosts_instagram");w.Close();};timer.Start();Call("SimpleWarpHosts");timer.Stop();Check(hostsSeen,"hosts remain accessible inside custom WARP via dedicated dialog");
  Mode(1);Page("Конструктор");Check(All<DataGrid>(main).Single(g=>g.Name=="simplePresetGrid").ActualHeight>=120,"VPN constructor remains usable in minimum window size");Save("compact-constructor");Mode(0);Page("Маршрутизация");main.UpdateLayout();var side=(DockPanel)Get("side");var scroll=side.Children.OfType<ScrollViewer>().Single();Check(scroll.ActualHeight>70&&scroll.ScrollableHeight>0,"full navigation scrolls independently above window behavior and switches");var behavior=(FrameworkElement)Get("minimizeChoice");Check(behavior.TranslatePoint(new Point(0,0),main).Y>scroll.TranslatePoint(new Point(0,scroll.ActualHeight),main).Y,"window behavior controls sit above connection switches without navigation overlap");Save("compact-standard-sidebar");Call("RequestExit");Wait(()=>(bool)Get("closing")&&!main.IsVisible);app.Shutdown();
