 [STAThread]static int Main(string[] args){try{string root=Path.GetFullPath(args[0]);output=args[1];if(Directory.Exists(root))throw new Exception("fresh profile required");app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};typeof(MainWindow).Assembly.GetType("Mcrf.Wpf.Program").GetMethod("LoadTheme",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{app});SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());Open(root);
