  string config="[Interface]\nPrivateKey=AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=\nAddress=172.16.0.2/32\n[Peer]\nPublicKey="+WarpScout.PeerPublicKey+"\nEndpoint=198.51.100.77:2408";var warp=Links.Read(config).Single();warp.Name="WARP fixture";session.State.Servers.Add(warp);Mode(2);typeof(MainWindow).GetField("simpleWarpTab",F).SetValue(main,1);Page("WARP");Check(All<DataGrid>(main).Any(g=>g.Name=="simplePresetGrid")&&All<Button>(main).Any(b=>b.Name=="simpleWarpHosts"),"custom WARP contains preset constructor and hosts controls");Finish((Task)Call("ApplySimplePresets",WarpOutputs.Tag(warp),new[]{preset},new RoutePreset[0],false,true,true,"warp.example"));session.State.WarpEnabled=true;session.State.VpnEnabled=false;var generated=new JavaScriptSerializer().Serialize(core.Build(session.State));Check(generated.Contains("mcrf-geoip-ru")&&generated.Contains("qbittorrent.exe")&&generated.Contains(WarpOutputs.Tag(warp)),"real WARP configuration includes selected route and Russia/torrent direct exceptions");core.Check(core.WriteConfig(session.State));Check(!core.Running,"WARP constructor config passes real native preflight without connecting");Save("no-vpn-custom-warp");Page("Обновления");Check(!All<ComboBox>(main).Single(c=>c.Name=="updatesType").Items.Cast<object>().Any(i=>Convert.ToString(i)=="Дополнительные движки"),"no-VPN updates hide optional engines");
